create table if not exists public.location_verification_points (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, points integer not null, reason text not null, created_at timestamptz not null default now()); create index if not exists idx_lvp_user on public.location_verification_points(user_id,created_at desc); create index if not exists idx_lvp_location on public.location_verification_points(location_id,created_at desc); create or replace function public.get_location_bathroom_verification(p_location_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); l public.locations%rowtype; pos integer:=0; neg integer:=0; total integer:=0; is_owner boolean:=false; status text; begin select * into l from public.locations where id=p_location_id; if not found then raise exception 'Location not found'; end if; select exists(select 1 from public.business_members bm where bm.business_id=l.business_id and bm.user_id=uid and lower(bm.role::text) in ('owner','admin','manager')) or exists(select 1 from public.app_business_memberships abm where abm.business_id=l.business_id and abm.user_id=uid and lower(abm.role::text) in ('owner','admin','manager')) into is_owner; if is_owner then update public.locations set bathroom_verification_status='verified',bathroom_verified_at=coalesce(bathroom_verified_at,now()) where id=p_location_id and bathroom_verification_status<>'verified'; status:='verified'; else status:=coalesce(l.bathroom_verification_status,'unverified'); end if; select count(*) filter(where has_public_bathroom),count(*) filter(where not has_public_bathroom),count(*) into pos,neg,total from public.location_bathroom_verifications where location_id=p_location_id; return jsonb_build_object('status',status,'positive',pos,'negative',neg,'total',total,'owner_verified',is_owner); end; $$; create or replace function public.record_bathroom_verification(p_location_id uuid,p_has_public_bathroom boolean,p_lat double precision,p_lng double precision) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); l public.locations%rowtype; pos integer; neg integer; total integer; status text; premium boolean:=false; owner boolean:=false; points integer:=0; begin if uid is null then raise exception 'Authentication required'; end if; select * into l from public.locations where id=p_location_id; if not found then raise exception 'Location not found'; end if; select exists(select 1 from public.profiles p where p.id=uid and lower(p.subscription_tier::text) in ('premium','pro','growth','enterprise')) into premium; select exists(select 1 from public.business_members bm where bm.business_id=l.business_id and bm.user_id=uid and lower(bm.role::text) in ('owner','admin','manager')) or exists(select 1 from public.app_business_memberships abm where abm.business_id=l.business_id and abm.user_id=uid and lower(abm.role::text) in ('owner','admin','manager')) into owner; if owner then status:=case when p_has_public_bathroom then 'verified' else 'not_a_bathroom' end; else if exists(select 1 from public.location_bathroom_verifications v where v.location_id=p_location_id and v.user_id=uid) then raise exception 'You already verified this location'; end if; if not premium and exists(select 1 from public.location_bathroom_verifications v where v.location_id=p_location_id and v.user_id=uid) then raise exception 'You already voted'; end if; if p_lat is null or p_lng is null then raise exception 'GPS location required'; end if; insert into public.location_bathroom_verifications(location_id,user_id,has_public_bathroom,verification_method,latitude,longitude,distance_meters) select p_location_id,uid,p_has_public_bathroom,'gps',p_lat,p_lng,round((2*6371000*asin(sqrt(power(sin(radians(p_lat-l.latitude)/2),2)+cos(radians(l.latitude))*cos(radians(p_lat))*power(sin(radians(p_lng-l.longitude)/2),2))))::numeric,1) where 2*6371000*asin(sqrt(power(sin(radians(p_lat-l.latitude)/2),2)+cos(radians(l.latitude))*cos(radians(p_lat))*power(sin(radians(p_lng-l.longitude)/2),2))) <= coalesce(l.geofence_radius_m,100); if not found then raise exception 'You must be at this location to verify it'; end if; end if; select count(*) filter(where has_public_bathroom),count(*) filter(where not has_public_bathroom),count(*) into pos,neg,total from public.location_bathroom_verifications where location_id=p_location_id; if owner or premium then status:=case when p_has_public_bathroom then 'verified' else 'not_a_bathroom' end; else status:=case when pos>=3 then 'verified' when neg>=3 and neg>pos then 'not_a_bathroom' else 'pending' end; end if; update public.locations set bathroom_verification_count=total,bathroom_positive_count=pos,bathroom_negative_count=neg,bathroom_verification_status=status,bathroom_verified_at=case when status in ('verified','not_a_bathroom') then coalesce(bathroom_verified_at,now()) else bathroom_verified_at end where id=p_location_id; points:=case when owner then 5 when premium then 15 else 10 end; insert into public.location_verification_points(user_id,location_id,points,reason) values(uid,p_location_id,points,case when owner then 'business_owner_bathroom_verification' when premium then 'premium_bathroom_verification' else 'community_bathroom_verification' end); update public.profiles set points=coalesce(points,0)+points,total_check_ins=coalesce(total_check_ins,0) where id=uid; return jsonb_build_object('status',status,'positive',pos,'negative',neg,'total',total,'points',points,'premium',premium,'owner_verified',owner); end; $$; grant execute on function public.get_location_bathroom_verification(uuid) to authenticated; grant execute on function public.record_bathroom_verification(uuid,boolean,double precision,double precision) to authenticated;
